import{_ as r,a0 as n,w as p,s as o,I as t,x as e,a1 as s,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"用 PGP 保護代碼完整性（二）：生成你的主密鑰 | LCTT x X-CMD","titleTemplate":false,"description":"用 PGP 保護代碼完整性（二）：生成你的主密鑰 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 PGP 保護代碼完整性（二）：生成你的主密鑰 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 PGP 保護代碼完整性（二）：生成你的主密鑰 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180221 Protecting Code Integrity with PGP - Part 2- Generating Your Master Key","title":"用 PGP 保護代碼完整性（二）：生成你的主密鑰","tag":"201804","desc":""},"relativePath":"201804/20180221 Protecting Code Integrity with PGP - Part 2- Generating Your Master Key.md","filePath":"[post].md"}'),g={name:"201804/20180221 Protecting Code Integrity with PGP - Part 2- Generating Your Master Key.md"};function h(u,i,k,b,c,f){const a=n("Link");return p(),o("div",null,[i[19]||(i[19]=t("h1",{id:"用-pgp-保護代碼完整性-二-生成你的主密鑰",tabindex:"-1"},[e("用 PGP 保護代碼完整性（二）：生成你的主密鑰 "),t("a",{class:"header-anchor",href:"#用-pgp-保護代碼完整性-二-生成你的主密鑰","aria-label":"Permalink to “用 PGP 保護代碼完整性（二）：生成你的主密鑰”"},"​")],-1)),i[20]||(i[20]=t("p",null,[t("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/binary-1538717_1920.png?itok=kv_sxSnf",alt:""})],-1)),t("p",null,[i[1]||(i[1]=e("在本系列文章中，我們將深度探討如何使用 PGP 以及為工作於自由軟件項目的開發者提供實用指南。在前一篇文章中，我們介紹了",-1)),s(a,{href:"https://linux.cn/article-9524-1.html"},{default:l(()=>[...i[0]||(i[0]=[e("基本工具和概念",-1)])]),_:1}),i[2]||(i[2]=e("。在本文中，我們將展示如何生成和保護你的 PGP 主密鑰。",-1))]),i[21]||(i[21]=d(`<h3 id="清單" tabindex="-1">清單 <a class="header-anchor" href="#清單" aria-label="Permalink to “清單”">​</a></h3><ol><li>生成一個 4096 位的 RSA 主密鑰 （必要）</li><li>使用 paperkey 備份你的 RSA 主密鑰 （必要）</li><li>添加所有相關的身份 （必要）</li></ol><h3 id="考慮事項" tabindex="-1">考慮事項 <a class="header-anchor" href="#考慮事項" aria-label="Permalink to “考慮事項”">​</a></h3><h3 id="理解-主-認證-密鑰" tabindex="-1">理解“主”（認證）密鑰 <a class="header-anchor" href="#理解-主-認證-密鑰" aria-label="Permalink to “理解“主”（認證）密鑰”">​</a></h3><p>在本節和下一節中，我們將討論“主密鑰”和“子密鑰”。理解以下內容很重要：</p><ol><li>在“主密鑰”和“子密鑰”之間沒有技術上的區別。</li><li>在創建時，我們賦予每個密鑰特定的能力來分配功能限制。</li><li>一個 PGP 密鑰有四項能力 * [S] 密鑰可以用於簽名 * [E] 密鑰可以用於加密 * [A] 密鑰可以用於身份認證 * [C] 密鑰可以用於認證其他密鑰</li><li>一個密鑰可能有多種能力</li></ol><p>帶有 [C] （認證）能力的密鑰被認為是“主”密鑰，因為它是唯一可以用來表明與其他密鑰關係的密鑰。只有 [C] 密鑰可以被用於：</p><ul><li>添加或撤銷其他密鑰（子密鑰）的 S/E/A 能力</li><li>添加、更改或撤銷密鑰關聯的身份（uid）</li><li>添加或更改本身或其他子密鑰的到期時間</li><li>為了網絡信任目的為其它密鑰簽名</li></ul><p>在自由軟件的世界裏，[C] 密鑰就是你的數字身份。一旦你創建該密鑰，你應該格外小心地保護它並且防止它落入壞人的手中。</p><h3 id="在你創建主密鑰前" tabindex="-1">在你創建主密鑰前 <a class="header-anchor" href="#在你創建主密鑰前" aria-label="Permalink to “在你創建主密鑰前”">​</a></h3><p>在你創建的你的主密鑰前，你需要選擇你的主要身份和主密碼。</p><h4 id="主要身份" tabindex="-1">主要身份 <a class="header-anchor" href="#主要身份" aria-label="Permalink to “主要身份”">​</a></h4><p>身份使用郵件中發件人一欄相同格式的字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Alice Engineer &lt;alice.engineer@example.org&gt;</span></span></code></pre></div><p>你可以在任何時候創建新的身份，取消舊的，並且更改你的“主要”身份。由於主要身份在所有 GnuPG 操作中都展示，你應該選擇正式的和最有可能用於 PGP 保護通信的名字和郵件地址，比如你的工作地址或者用於在項目<ruby>提交<rt>commit</rt></ruby>時簽名的地址。</p><h4 id="密碼" tabindex="-1">密碼 <a class="header-anchor" href="#密碼" aria-label="Permalink to “密碼”">​</a></h4><p><ruby>密碼<rt>passphrase</rt></ruby>專用於私鑰存儲在磁盤上時使用對稱加密算法對其進行加密。如果你的 <code>.gnupg</code> 目錄的內容被泄露，那麼一個好的密碼就是小偷能夠在線假冒你的最後一道防線，這就是為什麼設置一個好的密碼很重要的原因。</p><p>一個強密碼最好使用豐富或混合的詞典的 3-4 個詞，而不引用自流行來源（歌曲、書籍、口號）。由於你將相當頻繁地使用該密碼，所以它應當易於輸入和記憶。</p><h4 id="算法和密鑰強度" tabindex="-1">算法和密鑰強度 <a class="header-anchor" href="#算法和密鑰強度" aria-label="Permalink to “算法和密鑰強度”">​</a></h4><p>儘管現在 GnuPG 已經支持橢圓曲線加密一段時間了，但我們仍堅持使用 RSA 密鑰，至少較長一段時間會這樣。雖然現在就可以開始使用 ED25519 密鑰，但你可能會碰到無法正確處理它們的工具和硬件設備。</p><p>在後續的指南中我們説 2048 位的密鑰對 RSA 公鑰加密的生命週期已經足夠，你可能也會好奇主密鑰為什麼是 4096 位。 原因很大程度是由於社會因素而非技術上的：主密鑰在密鑰鏈上是最顯眼的，如果你的主密鑰位數比一些和你交互的開發者的少，他們肯定會鄙視你。</p><h4 id="生成主密鑰" tabindex="-1">生成主密鑰 <a class="header-anchor" href="#生成主密鑰" aria-label="Permalink to “生成主密鑰”">​</a></h4><p>為了生成你的主密鑰，請使用以下命令，並且將 “Alice Engineer” 替換為正確值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --quick-generate-key &#39;Alice Engineer &lt;alice@example.org&gt;&#39; rsa4096 cert</span></span></code></pre></div><p>這將彈出一個要求輸入密碼的對話框。然後，你可能需要移動鼠標或隨便按一些鍵才能生成足夠的熵，直到該命令完成。</p><p>查看命令輸出，它就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pub rsa4096 2017-12-06 [C] [expires: 2019-12-06]</span></span>
<span class="line"><span> 111122223333444455556666AAAABBBBCCCCDDDD</span></span>
<span class="line"><span>uid Alice Engineer &lt;alice@example.org&gt;</span></span></code></pre></div><p>注意第二行的長字符串 —— 它是你新生成的密鑰的完整指紋。密鑰 ID（Key ID）可以用以下三種不同形式表達：</p><ul><li><ruby>指紋<rt>Fingerprint</rt></ruby>，一個完整的 40 個字符的密鑰標識符</li><li><ruby>長密鑰 ID<rt>Long</rt></ruby>，指紋的最後 16 個字符（AAAABBBBCCCCDDDD）</li><li><ruby>短密鑰 ID<rt>Short</rt></ruby>，指紋的最後 8 個字符（CCCCDDDD）</li></ul><p>你應該避免使用 8 個字符的短密鑰 ID，因為它們不足夠唯一。</p><p>這裏，我建議你打開一個文本編輯器，複製你新密鑰的指紋並粘貼。你需要在接下來幾步中用到它，所以將它放在旁邊會很方便。</p><h4 id="備份你的主密鑰" tabindex="-1">備份你的主密鑰 <a class="header-anchor" href="#備份你的主密鑰" aria-label="Permalink to “備份你的主密鑰”">​</a></h4><p>出於災後恢復的目的 —— 同時特別的如果你試圖使用 Web of Trust 並且收集來自其他項目開發者的密鑰簽名 —— 你應該創建你的私鑰的硬拷貝備份。萬一所有其它的備份機制都失敗了，這應當是最後的補救措施。</p><p>創建一個你的私鑰的可打印的硬拷貝的最好方法是使用為此而寫的軟件 <code>paperkey</code>。<code>paperkey</code> 在所有 Linux 發行版上可用，在 Mac 上也可以通過 brew 安裝 <code>paperkey</code>。</p><p>運行以下命令，用你密鑰的完整指紋替換 <code>[fpr]</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --export-secret-key [fpr] | paperkey -o /tmp/key-backup.txt</span></span></code></pre></div><p>輸出將採用易於 OCR 或手動輸入的格式，以防如果你需要恢復它的話。打印出該文件，然後拿支筆，並在紙的邊緣寫下密鑰的密碼。這是必要的一步，因為密鑰輸出仍然使用密碼加密，並且如果你更改了密鑰的密碼，你不會記得第一次創建的密鑰是什麼 —— 我保證。</p><p>將打印結果和手寫密碼放入信封中，並存放在一個安全且保護好的地方，最好遠離你家，例如銀行保險庫。</p><p><strong>打印機注意事項</strong> 打印機連接到計算機的並行端口的時代已經過去了。現在他們擁有完整的操作系統，硬盤驅動器和雲集成。由於我們發送給打印機的關鍵內容將使用密碼進行加密，因此這是一項相當安全的操作，但請使用您最好的偏執判斷。</p><h4 id="添加相關身份" tabindex="-1">添加相關身份 <a class="header-anchor" href="#添加相關身份" aria-label="Permalink to “添加相關身份”">​</a></h4><p>如果你有多個相關的郵件地址（個人、工作、開源項目等），你應該將其添加到主密鑰中。你不需要為任何你不希望用於 PGP 的地址（例如，可能不是你的校友地址）這樣做。</p><p>該命令是（用你完整的密鑰指紋替換 <code>[fpr]</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --quick-add-uid [fpr] &#39;Alice Engineer &lt;allie@example.net&gt;&#39;</span></span></code></pre></div><p>你可以查看你已經使用的 UID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --list-key [fpr] | grep ^uid</span></span></code></pre></div><h4 id="選擇主-uid" tabindex="-1">選擇主 UID <a class="header-anchor" href="#選擇主-uid" aria-label="Permalink to “選擇主 UID”">​</a></h4><p>GnuPG 將會把你最近添加的 UID 作為你的主 UID，如果這與你想的不同，你應該改回來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --quick-set-primary-uid [fpr] &#39;Alice Engineer &lt;alice@example.org&gt;&#39;</span></span></code></pre></div><p>下次，我們將介紹如何生成 PGP 子密鑰，它是你實際用於日常工作的密鑰。</p>`,49)),t("p",null,[i[4]||(i[4]=e("通過 Linux 基金會和 edX 的免費",-1)),s(a,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:l(()=>[...i[3]||(i[3]=[e("“Introduction to Linux” ",-1)])]),_:1}),i[5]||(i[5]=e("課程瞭解關於 Linux 的更多信息。",-1))]),i[22]||(i[22]=t("hr",null,null,-1)),t("p",null,[i[7]||(i[7]=e("via: ",-1)),s(a,{href:"https://www.linux.com/blog/learn/PGP/2018/2/protecting-code-integrity-pgp-part-2-generating-and-protecting-your-master-pgp-key"},{default:l(()=>[...i[6]||(i[6]=[e("https://www.linux.com/blog/learn/PGP/2018/2/protecting-code-integrity-pgp-part-2-generating-and-protecting-your-master-pgp-key",-1)])]),_:1})]),t("p",null,[i[11]||(i[11]=e("作者：",-1)),s(a,{href:"https://www.linux.com/users/mricon"},{default:l(()=>[...i[8]||(i[8]=[e("KONSTANTIN RYABITSEV",-1)])]),_:1}),i[12]||(i[12]=e(" 譯者：",-1)),s(a,{href:"https://github.com/kimii"},{default:l(()=>[...i[9]||(i[9]=[e("kimii",-1)])]),_:1}),i[13]||(i[13]=e(" 校對：",-1)),s(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[10]||(i[10]=[e("wxy",-1)])]),_:1})]),t("p",null,[i[16]||(i[16]=e("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[14]||(i[14]=[e("LCTT",-1)])]),_:1}),i[17]||(i[17]=e(" 原創編譯，",-1)),s(a,{href:"https://linux.cn/"},{default:l(()=>[...i[15]||(i[15]=[e("Linux中國",-1)])]),_:1}),i[18]||(i[18]=e(" 榮譽推出",-1))])])}const x=r(g,[["render",h]]);export{y as __pageData,x as default};
